sys_script_client.script:
function onSubmit() {
    // 尝试设置状态字段为"submitted"
    try {
        // 检查是否已经设置了状态（防止覆盖已有状态）
        if (!g_form.getValue('my_request_status')) {
            g_form.setValue('my_request_status', 'Requested');
        }

        // 验证必填字段
        if (!g_form.getValue('computer_model')) {
            g_form.addErrorMessage('请选择电脑型号');
            return false; // 阻止提交
        }

        if (!g_form.getValue('request_for_dr')) {
            g_form.addErrorMessage('请选择申请对象');
            return false; // 阻止提交
        }

        return true; // 允许提交
    } catch (e) {
        g_form.addErrorMessage('提交时出错: ' + e.message);
        return false; // 阻止提交
    }
}
